<?php $money=static fn(float $v):string=>'KES '.number_format($v,2);$summary=$summary??['rows'=>[],'reconciled'=>[],'total'=>0];$date=(string)($date??date('Y-m-d')); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Reconciliation | EduSasa</title><style>body{font-family:system-ui,sans-serif;background:#f6f7fb;color:#172033;margin:0}.wrap{max-width:1200px;margin:30px auto;padding:0 18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-bottom:16px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #eee;text-align:left}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.value{font-size:22px;font-weight:700;margin-top:5px}.muted{color:#667085}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:end}input,textarea{padding:9px;border:1px solid #ccd1db;border-radius:8px}button,a{padding:9px 13px;border-radius:8px;border:0;background:#172033;color:#fff;text-decoration:none}.ok{font-weight:700}</style></head><body><main class="wrap"><div class="actions"><a href="/finance">← Finance</a><form method="get"><label>Date <input type="date" name="date" value="<?= htmlspecialchars($date) ?>"></label><button>Load</button></form></div><section class="card"><h1>Payment Reconciliation</h1><p class="muted">Compare confirmed collections with the amount physically received or verified for each payment method.</p></section><section class="grid"><div class="card"><span class="muted">Confirmed collections</span><div class="value"><?= $money((float)$summary['total']) ?></div></div><div class="card"><span class="muted">Methods</span><div class="value"><?= count($summary['rows']) ?></div></div><div class="card"><span class="muted">Reconciliations</span><div class="value"><?= count($summary['reconciled']) ?></div></div></section><section class="card"><h2>By payment method</h2><table><thead><tr><th>Method</th><th>Payments</th><th>Expected</th><th>Actual</th><th>Variance</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($summary['rows'] as $row): $existing=null;foreach($summary['reconciled'] as $r){if($r['method']===$row['method']){$existing=$r;break;}} ?><tr><td><?= htmlspecialchars(strtoupper($row['method'])) ?></td><td><?= (int)$row['payment_count'] ?></td><td><?= $money((float)$row['total']) ?></td><td><?= $existing?$money((float)$existing['actual_amount']):'—' ?></td><td><?= $existing?$money((float)$existing['variance']):'—' ?></td><td><?= $existing?htmlspecialchars($existing['status']):'Open' ?></td><td><?php if(!$existing||$existing['status']==='open'): ?><form method="post" class="actions"><input type="hidden" name="date" value="<?= htmlspecialchars($date) ?>"><input type="hidden" name="method" value="<?= htmlspecialchars($row['method']) ?>"><?php if($existing): ?><input type="hidden" name="id" value="<?= (int)$existing['id'] ?>"><?php endif; ?><input type="number" step="0.01" min="0" name="actual_amount" placeholder="Actual" value="<?= $existing?htmlspecialchars((string)$existing['actual_amount']):'' ?>" required><input name="notes" placeholder="Notes" value="<?= $existing?htmlspecialchars((string)($existing['notes']??'')):'' ?>"><button formaction="/finance/reconciliation/save">Save</button><?php if($existing): ?><button formaction="/finance/reconciliation/confirm">Confirm</button><?php endif; ?></form><?php else: ?><span class="ok">Reconciled</span><?php endif; ?></td></tr><?php endforeach;if(!$summary['rows']): ?><tr><td colspan="7" class="muted">No confirmed payments for this date.</td></tr><?php endif; ?></tbody></table></section></main></body></html>
